SELECT
    cast(`key` AS STRING) AS externalId
  , CASE WHEN `corrosionRateMmPerYr` IS NOT NULL AND trim(cast(`corrosionRateMmPerYr` AS STRING)) != '' THEN cast(`corrosionRateMmPerYr` AS DOUBLE) ELSE NULL END AS `corrosionRateMmPerYr`
  , cast(`findings` AS STRING) AS `findings`
  , CASE WHEN `inspectionDate` IS NOT NULL AND trim(cast(`inspectionDate` AS STRING)) != '' THEN to_timestamp(`inspectionDate`) ELSE NULL END AS `inspectionDate`
  , cast(`inspectionEffectiveness` AS STRING) AS `inspectionEffectiveness`
  , cast(`measuredBy` AS STRING) AS `measuredBy`
  , CASE WHEN `measuredThicknessMm` IS NOT NULL AND trim(cast(`measuredThicknessMm` AS STRING)) != '' THEN cast(`measuredThicknessMm` AS DOUBLE) ELSE NULL END AS `measuredThicknessMm`
  , cast(`measurementId` AS STRING) AS `measurementId`
  , cast(`name` AS STRING) AS `name`
  , CASE WHEN `positionX` IS NOT NULL AND trim(cast(`positionX` AS STRING)) != '' THEN cast(`positionX` AS DOUBLE) ELSE NULL END AS `positionX`
  , CASE WHEN `positionY` IS NOT NULL AND trim(cast(`positionY` AS STRING)) != '' THEN cast(`positionY` AS DOUBLE) ELSE NULL END AS `positionY`
  , CASE WHEN `positionZ` IS NOT NULL AND trim(cast(`positionZ` AS STRING)) != '' THEN cast(`positionZ` AS DOUBLE) ELSE NULL END AS `positionZ`
  , cast(`technique` AS STRING) AS `technique`
FROM `{{energyBaseRawDb}}`.`WallThicknessMeasuringPoint`
